// Content with portions generated by generative AI platform
package org.eclipse.kura.web.server.net2.configuration;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;

import org.eclipse.kura.web.shared.model.GwtNetInterfaceConfig;
import org.eclipse.kura.web.shared.model.GwtNetRouterMode;
import org.junit.Test;

public class GwtNetInterfaceConfigBuilderDhcpServerTest {

    private static final String INTERFACE_NAME = "eth1";
    private static final String PREFIX = "net.interface.eth1.config.";

    private final Map<String, Object> properties = new HashMap<>();
    private GwtNetInterfaceConfig gwtConfig;

    /*
     * Scenarios
     */

    @Test
    public void storedDhcpServerValuesAreReadWhenDhcpServerIsDisabled() {
        givenEthernetInterface();
        givenDhcpServerEnabled(false);
        givenStoredDhcpServerValues();

        whenBuildingGwtConfig();

        thenRouterModeIs(GwtNetRouterMode.netRouterOff);
        thenStoredDhcpServerValuesAreShown();
    }

    @Test
    public void dhcpServerFieldsAreEmptyWhenDisabledAndNothingIsStored() {
        givenEthernetInterface();
        givenDhcpServerEnabled(false);

        whenBuildingGwtConfig();

        thenRouterModeIs(GwtNetRouterMode.netRouterOff);
        thenDhcpServerFieldsAreEmpty();
    }

    @Test
    public void dhcpServerFieldsAreEmptyWhenDisabledAndOnlyMetatypeDefaultsAreStored() {
        givenEthernetInterface();
        givenDhcpServerEnabled(false);
        givenDhcpServerMetatypeDefaults();

        whenBuildingGwtConfig();

        thenRouterModeIs(GwtNetRouterMode.netRouterOff);
        thenDhcpServerFieldsAreEmpty();
    }

    @Test
    public void storedDhcpServerValuesAreReadWhenDhcpServerIsEnabled() {
        givenEthernetInterface();
        givenDhcpServerEnabled(true);
        givenStoredDhcpServerValues();

        whenBuildingGwtConfig();

        thenRouterModeIs(GwtNetRouterMode.netRouterDchp);
        thenStoredDhcpServerValuesAreShown();
    }

    /*
     * Steps
     */

    private void givenEthernetInterface() {
        this.properties.put("net.interfaces", INTERFACE_NAME);
        this.properties.put("net.interface.eth1.type", "ETHERNET");
        this.properties.put(PREFIX + "ip4.status", "netIPv4StatusEnabledLAN");
        this.properties.put(PREFIX + "dhcpClient4.enabled", false);
        this.properties.put(PREFIX + "nat.enabled", false);
    }

    private void givenDhcpServerEnabled(boolean enabled) {
        this.properties.put(PREFIX + "dhcpServer4.enabled", enabled);
    }

    private void givenDhcpServerMetatypeDefaults() {
        this.properties.put(PREFIX + "dhcpServer4.prefix", (short) -1);
        this.properties.put(PREFIX + "dhcpServer4.defaultLeaseTime", -1);
        this.properties.put(PREFIX + "dhcpServer4.maxLeaseTime", -1);
        this.properties.put(PREFIX + "dhcpServer4.passDns", false);
    }

    private void givenStoredDhcpServerValues() {
        this.properties.put(PREFIX + "dhcpServer4.rangeStart", "192.168.5.100");
        this.properties.put(PREFIX + "dhcpServer4.rangeEnd", "192.168.5.110");
        this.properties.put(PREFIX + "dhcpServer4.prefix", (short) 24);
        this.properties.put(PREFIX + "dhcpServer4.defaultLeaseTime", 3600);
        this.properties.put(PREFIX + "dhcpServer4.maxLeaseTime", 9000);
        this.properties.put(PREFIX + "dhcpServer4.passDns", true);
    }

    private void whenBuildingGwtConfig() {
        this.gwtConfig = new GwtNetInterfaceConfigBuilder(this.properties).forInterface(INTERFACE_NAME).build();
    }

    private void thenRouterModeIs(GwtNetRouterMode expected) {
        assertEquals(expected.name(), this.gwtConfig.getRouterMode());
    }

    private void thenStoredDhcpServerValuesAreShown() {
        assertEquals("192.168.5.100", this.gwtConfig.getRouterDhcpBeginAddress());
        assertEquals("192.168.5.110", this.gwtConfig.getRouterDhcpEndAddress());
        assertEquals("255.255.255.0", this.gwtConfig.getRouterDhcpSubnetMask());
        assertEquals(3600, this.gwtConfig.getRouterDhcpDefaultLease());
        assertEquals(9000, this.gwtConfig.getRouterDhcpMaxLease());
        assertTrue(this.gwtConfig.getRouterDnsPass());
    }

    private void thenDhcpServerFieldsAreEmpty() {
        assertNull(this.gwtConfig.getRouterDhcpBeginAddress());
        assertNull(this.gwtConfig.getRouterDhcpEndAddress());
        assertNull(this.gwtConfig.getRouterDhcpSubnetMask());
        assertEquals(0, this.gwtConfig.getRouterDhcpDefaultLease());
        assertEquals(0, this.gwtConfig.getRouterDhcpMaxLease());
        assertFalse(this.gwtConfig.getRouterDnsPass());
    }
}
